"use strict";const $=s=>document.querySelector(s),esc=v=>String(v).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));let data={updates:[]};function render(){const q=$('#search').value.toLowerCase(),p=$('#product').value,y=$('#year').value,m=$('#month').value,t=$('#type').value;const list=data.updates.filter(x=>(!p||x.product===p)&&(!y||x.releaseDate.startsWith(y))&&(!m||x.releaseDate.startsWith(m))&&(!t||x.updateType===t)&&(!q||JSON.stringify(x).toLowerCase().includes(q)));const groups=Map.groupBy(list,x=>x.product);$('#content').innerHTML=[...groups].map(([product,rows])=>`<section class="product"><h2>${esc(product)}</h2>${[...Map.groupBy(rows,x=>x.featureVersion)].map(([version,items])=>`<section class="version card"><h3>Version ${esc(version)}<span class="meta">${items.length} update${items.length===1?'':'s'}</span></h3><div class="table-wrap"><table class="update-table"><thead><tr><th>KB</th><th>Date</th><th>Type</th><th>OS Build</th><th>Docs</th></tr></thead><tbody>${items.map(x=>`<tr><td class="kb-cell"><a href="${esc(x.documentationUrl)}" target="_blank" rel="noopener noreferrer">${esc(x.kb)}</a></td><td>${new Date(x.releaseDate+'T00:00:00Z').toLocaleDateString('en-US',{day:'2-digit',month:'short',year:'numeric'})}</td><td><span class="type-pill ${esc(x.updateType.toLowerCase().replace(/[^a-z]+/g,'-').replace(/^-|-$/g,''))}">${esc(x.updateType)}</span></td><td class="mono">${esc(x.osBuilds.join(', '))}</td><td class="doc-cell"><a class="btn btn-secondary btn-sm" href="${esc(x.documentationUrl)}" target="_blank" rel="noopener noreferrer">Open</a></td></tr>`).join('')}</tbody></table></div></section>`).join('')}</section>`).join('')||'<p class="empty">No matching updates.</p>'}function populateFilters(){const product=$('#product');product.innerHTML='<option value="">All</option>'+[...new Set(data.updates.map(x=>x.product))].sort().map(x=>`<option value="${x}">${x}</option>`).join('');const year=$('#year');year.innerHTML='<option value="">All years</option>'+[...new Set(data.updates.map(x=>x.releaseDate.slice(0,4)))].sort().reverse().map(x=>`<option value="${x}">${x}</option>`).join('');const month=$('#month');month.innerHTML='<option value="">All months</option>'+[...new Set(data.updates.map(x=>x.releaseDate.slice(0,7)))].sort().reverse().map(x=>`<option value="${x}">${new Date(x+'-01T00:00:00Z').toLocaleString('en-US',{month:'long',year:'numeric'})}</option>`).join('');}fetch('data/updates.json',{cache:'no-store'}).then(r=>{if(!r.ok)throw Error(r.status);return r.json()}).then(x=>{data=x;populateFilters();$('#sync').textContent=`Microsoft synchronization: ${new Date(x.generatedAt).toLocaleString('en-US')}${x.sourceErrors.length?` · ${x.sourceErrors.length} source errors`:''}`;render()}).catch(()=>{$('#sync').classList.add('error');$('#sync').textContent='Live data could not be loaded.'});['search','product','year','month','type'].forEach(x=>$('#'+x).addEventListener('input',render));['product','year','month','type'].forEach(x=>$('#'+x).addEventListener('change',render));const root=document.documentElement,themeBtn=$('#theme');function syncTheme(){const light=root.dataset.theme==='light',label=light?'Switch to dark mode':'Switch to light mode';themeBtn.textContent=light?'\u2600':'\u263E';themeBtn.setAttribute('aria-label',label);themeBtn.title=label;document.querySelector('meta[name="theme-color"]').setAttribute('content',light?'#f4f8fb':'#0b1120')}themeBtn.addEventListener('click',()=>{const light=root.dataset.theme!=='light';if(light)root.dataset.theme='light';else delete root.dataset.theme;try{localStorage.setItem('theme',light?'light':'dark')}catch(e){}syncTheme()});syncTheme();